package com.yuegang.zhihui.admin.application;import com.yuegang.zhihui.admin.security.*;import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)class AdminConfiguration{@Bean AdminDashboardService adminDashboardService(@Value("${ygh.admin.service-health-urls}")String u){return new AdminDashboardService(u);}@Bean AdminUserVerifier adminUserVerifier(@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new AdminUserVerifier(k);}finally{Arrays.fill(k,(byte)0);}}}
